#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
ANNBLACKBOX — Custom Firmware Installer (Windows)
=================================================

Install a CUSTOM firmware on the Sinco BlackBox pedal — or flash it back to the
factory V20 — exactly like the official ANNBLACKBOX updater does it: this tool
drives the *real* vendor application (M-UPGRADE-NTFS-BLACKBOX.exe) and only
swaps, in a working copy of it, the firmware image that the vendor binary carries
embedded, plus the two same-version guards that would otherwise refuse the write.
The vendor's own OTA engine performs the whole flash; nothing is re-implemented.

Three actions:  Install custom firmware / Restore V20 factory / Cancel
Everything is automatic: patch, launch, auto-start the vendor's
"Update the firmware" button (keyboard-only — the mouse cursor never moves) and
follow the vendor log to report the result.

Created by entitymar                  — https://entitymar.pages.dev/
GitHub: github.com/entitymar/annblackbox-custom-firmware-installer

Windows + Python 3.8+ (tkinter). No third-party modules.
"""

import os
import sys
import time
import json
import shutil
import hashlib
import subprocess
import threading
import tempfile
import queue
import webbrowser
from pathlib import Path

HERE = Path(__file__).resolve().parent

# ---------------------------------------------------------------- files/paths
VENDOR_DIR   = HERE / "windows" / "official-updater"
VENDOR_EXE   = VENDOR_DIR / "M-UPGRADE-NTFS-BLACKBOX.exe"
PRISTINE_EXE = HERE / "windows" / "M-UPGRADE-NTFS-BLACKBOX.exe.pristine"
FIRMWARE_DIR = HERE / "firmware"
CUSTOM_FW    = FIRMWARE_DIR / "ANNBLACKBOX_custom.fwsc"
FACTORY_FW   = FIRMWARE_DIR / "BlackBox_FACTORY_V20.fwsc"
LOG_DIR      = VENDOR_DIR / "LOG"
LOGS_DIR     = HERE / "logs"

# ------------------------------------------------- verified binary constants
# The vendor exe carries its 700,436-byte BlackBox firmware image in ONE
# contiguous block; both official and custom .fwsc files are exactly that size,
# so the swap is byte-for-byte in place.
FW_OFFSET = 0x2E66BF
FW_SIZE   = 700436

# Guard #1 — "Cannot update the same firmware!" refusal (start-time check).
#   cmp dword [r14+0xC8], eax   ; device version vs firmware version
#   jne <proceed>               ; 0F 85 13 01 00 00  ->  90 E9 13 01 00 00
#   (forced to always proceed)
SITE_VERSION_OFFSET = 0x31C7A
SITE_VERSION_ORIG   = b"\x0f\x85\x13\x01\x00\x00"
SITE_VERSION_PATCH  = b"\x90\xe9\x13\x01\x00\x00"

# Guard #2 — connect-time UI gate ("Already the latest version" -> button stays
# enabled).   jg <new-version-branch>  ; 7F 32 -> EB 32  (forced jump)
SITE_UIGATE_OFFSET  = 0x32762
SITE_UIGATE_ORIG    = b"\x7f\x32"
SITE_UIGATE_PATCH   = b"\xeb\x32"

PRISTINE_SHA256 = "9444eb6e89afd3772487782e5852a6a182cf38eb00ad9b34cbad4e4b7c6997b8"

WINDOW_TITLE_HINT = "M-UPGRADE"          # vendor main-window title: M-UPGRADE-NTFS

# Vendor log phrases (from the vendor binary's own message catalog)
MSG_OTA_START    = ("All pre-checks passed", "Starting OTA upgrade process",
                    "Upgrade mode command sent successfully")
MSG_OTA_SUCCESS  = ("Second step (upgrade) completed",
                    "OTA upgrade process completed successfully",
                    "Upgrade completed!")
MSG_OTA_FAIL     = ("Verification timeout", "Upgrade timeout", "OTA upgrade failed")
MSG_CONNECTED    = ("Device connected successfully", "Connected to device")

# only these vendor log lines are forwarded to the UI (the rest is per-request
# debug noise — the full vendor logs stay in windows/official-updater/LOG/)
MSG_DISPLAY = ("Parsed OTA file", "OTA file parsed", "Selected device",
               "USB open result", "Connected to device",
               "Device connected successfully", "All pre-checks passed",
               "Starting OTA", "OTA upgrade process started",
               "Upgrade mode command sent", "First step", "Second step",
               "OTA upgrade process completed", "Upgrade completed",
               "Verification timeout", "Upgrade timeout", "OTA upgrade failed",
               "skipping duplicate start", "Device in OTA mode")

CREDITS_AUTHOR_TEXT = "created by entitymar"
CREDITS_AUTHOR_URL  = "https://entitymar.pages.dev/"
CREDITS_REPO_TEXT   = "github.com/entitymar/annblackbox-custom-firmware-installer"
CREDITS_REPO_URL    = "https://github.com/entitymar/annblackbox-custom-firmware-installer"

# ------------------------------------------------------------------ palette
BG      = "#151515"
