# --------------------------------------------------- tiny user-state helpers
def _state_file() -> Path:
    base = os.environ.get("LOCALAPPDATA") or str(Path.home())
    return Path(base) / "annblackbox-installer.json"


def _read_state() -> dict:
    try:
        return json.loads(_state_file().read_text(encoding="utf-8"))
    except Exception:                                     # noqa: BLE001
        return {}


def _write_state(state: dict) -> None:
    try:
        _state_file().write_text(json.dumps(state), encoding="utf-8")
    except Exception:                                     # noqa: BLE001
        pass


def load_last_dir():
    """Folder of the last firmware picked, so the dialog reopens there."""
    return _read_state().get("last_dir")


def save_last_dir(directory: str) -> None:
    s = _read_state(); s["last_dir"] = directory; _write_state(s)


def load_last_file():
    """Path of the last firmware file the user flashed (recovery candidate)."""
    p = _read_state().get("last_file")
    return Path(p) if p else None


def save_last_file(path) -> None:
    s = _read_state(); s["last_file"] = str(path); _write_state(s)


# --------------------------------------------------------------- run logs
_RUN_LOG = None


def open_run_log(tag: str = "run"):
    """Start a fresh per-run log file in ./logs/ (UI lines + raw vendor log
    lines). Returns its path, or None if logging is unavailable."""
    global _RUN_LOG
    try:
        LOGS_DIR.mkdir(exist_ok=True)
        _RUN_LOG = LOGS_DIR / time.strftime(f"annblackbox-%Y%m%d-%H%M%S-{tag}.log")
        flog(f"=== ANNBLACKBOX Custom Firmware Installer — run log ({tag}) ===")
        flog(f"    firmware files: "
             f"custom={'ok' if CUSTOM_FW.is_file() else 'MISSING'}, "
             f"factory={'ok' if FACTORY_FW.is_file() else 'MISSING'}")
        return _RUN_LOG
    except Exception:                                     # noqa: BLE001
        _RUN_LOG = None
        return None


def flog(line: str) -> None:
    """Append one line to the current run log (no-op if none is open)."""
    if _RUN_LOG is None:
        return
    try:
        with open(_RUN_LOG, "a", encoding="utf-8") as fh:
            fh.write(f"{time.strftime('%H:%M:%S')}  {line}\n")
    except Exception:                                     # noqa: BLE001
        pass


def ensure_firmware_files():
    """Restore the bundled firmwares from the copies embedded in this file if
    they are missing — the automatic stall-recovery needs BOTH of them."""
    import base64
    restored = []
    for name, b64 in BUILTIN_FIRMWARE.items():
        target = FIRMWARE_DIR / name
        if not target.is_file():
            try:
                FIRMWARE_DIR.mkdir(exist_ok=True)
                target.write_bytes(base64.b64decode(b64))
                restored.append(name)
            except Exception:                             # noqa: BLE001
                pass
    return restored


# ===========================================================================
#  Firmware / binary patching engine
# ===========================================================================
def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


class PatchError(RuntimeError):
    pass


def check_environment(fw_path: Path) -> None:
    """Validate every file involved BEFORE touching anything."""
    for p in (VENDOR_EXE, PRISTINE_EXE, fw_path):
        if not p.is_file():
            raise PatchError(f"missing file: {p}")
    if PRISTINE_EXE.stat().st_size != 13272576:
        raise PatchError("pristine vendor exe has unexpected size")
    if sha256_file(PRISTINE_EXE) != PRISTINE_SHA256:
        raise PatchError("pristine vendor exe was modified (sha256 mismatch)")
    if fw_path.stat().st_size != FW_SIZE:
        raise PatchError(f"{fw_path.name}: not a {FW_SIZE}-byte ANNBLACKBOX .fwsc")
    if not VENDOR_DIR.is_dir():
        raise PatchError(f"missing vendor folder: {VENDOR_DIR}")


def build_patched_exe(fw_path: Path) -> dict:
    """Restore the pristine exe over the working copy, then apply the three
    byte patches for *fw_path*.  Every write is read back and verified."""
    check_environment(fw_path)

    # 1. working copy <- pristine  (never patch the pristine itself).
    #    A leftover updater process keeps the exe locked — retry and, if
    #    needed, force-stop it before giving up.
    copied, last_exc = False, None
    for attempt in range(10):
        try:
            shutil.copyfile(PRISTINE_EXE, VENDOR_EXE)
            copied = True
            break
        except PermissionError as exc:
            last_exc = exc
            if attempt == 2:
                kill_vendor_processes()
            time.sleep(0.6)
    if not copied:
        raise PatchError(
            "cannot write the vendor exe — it is still locked by a running "
            "M-UPGRADE-NTFS updater; close it and retry") from last_exc

    fw_bytes = fw_path.read_bytes()

    if VENDOR_EXE.stat().st_size < FW_OFFSET + FW_SIZE:
        raise PatchError("vendor exe truncated (firmware block out of range)")

    # 2. apply patches in place
    with open(VENDOR_EXE, "r+b") as fh:
        fh.seek(SITE_VERSION_OFFSET)
        if fh.read(len(SITE_VERSION_ORIG)) != SITE_VERSION_ORIG:
            raise PatchError("version-guard signature not found (wrong vendor build?)")
        fh.seek(SITE_UIGATE_OFFSET)
        if fh.read(len(SITE_UIGATE_ORIG)) != SITE_UIGATE_ORIG:
            raise PatchError("UI-gate signature not found (wrong vendor build?)")

        fh.seek(FW_OFFSET)
        fh.write(fw_bytes)
        fh.seek(SITE_VERSION_OFFSET)
        fh.write(SITE_VERSION_PATCH)
        fh.seek(SITE_UIGATE_OFFSET)
        fh.write(SITE_UIGATE_PATCH)
        fh.flush()
        os.fsync(fh.fileno())

    # 3. read-back verification
    with open(VENDOR_EXE, "rb") as fh:
        fh.seek(FW_OFFSET)
        if fh.read(FW_SIZE) != fw_bytes:
            raise PatchError("firmware read-back mismatch")
        fh.seek(SITE_VERSION_OFFSET)
        if fh.read(len(SITE_VERSION_PATCH)) != SITE_VERSION_PATCH:
            raise PatchError("version-guard read-back mismatch")
        fh.seek(SITE_UIGATE_OFFSET)
        if fh.read(len(SITE_UIGATE_PATCH)) != SITE_UIGATE_PATCH:
            raise PatchError("UI-gate read-back mismatch")

    return {
        "exe": VENDOR_EXE,
        "firmware": fw_path.name,
        "firmware_sha256": hashlib.sha256(fw_bytes).hexdigest(),
    }


def restore_pristine() -> None:
    shutil.copyfile(PRISTINE_EXE, VENDOR_EXE)


# ===========================================================================
#  Win32 automation (keyboard-only auto-start — the cursor never moves)
# ===========================================================================
if IS_WINDOWS:
    import ctypes
    from ctypes import wintypes

    _user32 = ctypes.windll.user32

    WM_CLOSE   = 0x0010
    VK_MENU    = 0x12
    SW_SHOW    = 5
    SW_RESTORE = 9

    WNDENUMPROC = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

    _user32.EnumWindows.argtypes = [WNDENUMPROC, wintypes.LPARAM]
    _user32.EnumWindows.restype = wintypes.BOOL
    _user32.GetWindowTextW.argtypes = [wintypes.HWND, wintypes.LPWSTR, ctypes.c_int]
    _user32.GetWindowTextLengthW.argtypes = [wintypes.HWND]
    _user32.IsWindowVisible.argtypes = [wintypes.HWND]
    _user32.GetWindowThreadProcessId.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.DWORD)]
    _user32.PostMessageW.argtypes = [wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
    _user32.ShowWindow.argtypes = [wintypes.HWND, ctypes.c_int]
    _user32.SetForegroundWindow.argtypes = [wintypes.HWND]
    _user32.MapVirtualKeyW.argtypes = [wintypes.UINT, wintypes.UINT]

    def enum_windows():
        out = []

        def _cb(hwnd, _lparam):
            if _user32.IsWindowVisible(hwnd):
                n = _user32.GetWindowTextLengthW(hwnd)
                if n:
                    buf = ctypes.create_unicode_buffer(n + 1)
                    _user32.GetWindowTextW(hwnd, buf, n + 1)
                    pid = wintypes.DWORD()
                    _user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
                    out.append((hwnd, pid.value, buf.value))
            return True

        _user32.EnumWindows(WNDENUMPROC(_cb), 0)
        return out

    def find_vendor_window(pid=None):
        """Top-level visible window of the vendor updater (optionally of `pid`)."""
        for hwnd, wpid, title in enum_windows():
            if WINDOW_TITLE_HINT.lower() in title.lower():
                if pid is None or wpid == pid:
                    return hwnd, wpid, title
        return None

    def activate_window(hwnd):
        """Show + foreground the window (ALT trick); never moves the cursor."""
        try:
            _user32.ShowWindow(hwnd, SW_SHOW)
            _user32.ShowWindow(hwnd, SW_RESTORE)
            ctypes.windll.user32.keybd_event(VK_MENU, 0, 0, 0)
            _user32.SetForegroundWindow(hwnd)
            ctypes.windll.user32.keybd_event(VK_MENU, 0, 2, 0)  # KEYEVENTF_KEYUP
        except Exception:
            pass

    # "Update the firmware" button: QRect(140, 100, 281, 61) client coords in
    # the vendor's fixed 574x286 main window -> center (280, 130).
    BTN_UPDATE_X, BTN_UPDATE_Y = 280, 130

    def post_click(hwnd, x=BTN_UPDATE_X, y=BTN_UPDATE_Y):
        """Synthetic click on the vendor's 'Update the firmware' button.

        The messages are POSTED to the window (mouse-move + left down/up), so
        Windows never warps the visible cursor: nothing moves on screen."""
        lp = (y << 16) | (x & 0xFFFF)
        WM_MOUSEMOVE, WM_LBUTTONDOWN, WM_LBUTTONUP = 0x0200, 0x0201, 0x0202
        _user32.PostMessageW(hwnd, WM_MOUSEMOVE, 0, lp)
        time.sleep(0.10)
        _user32.PostMessageW(hwnd, WM_LBUTTONDOWN, 1, lp)
        time.sleep(0.12)
        _user32.PostMessageW(hwnd, WM_LBUTTONUP, 0, lp)

    def auto_start_upgrade(hwnd):
        """Activate the vendor's 'Update the firmware' button with a posted
        click while the window is shown/foregrounded — the cursor never moves."""
        activate_window(hwnd)
        time.sleep(0.4)
        post_click(hwnd)

    def _pid_image_path(pid):
        """Full image path of a running process (or None)."""
        try:
            k32 = ctypes.windll.kernel32
            PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
            h = k32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
            if not h:
                return None
            try:
                buf = ctypes.create_unicode_buffer(1024)
                size = ctypes.c_ulong(1024)
                ok = k32.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(size))
                return buf.value if ok else None
            finally:
                k32.CloseHandle(h)
        except Exception:                                  # noqa: BLE001
            return None

    def kill_vendor_processes(wait=6.0):
        """Force-stop M-UPGRADE-NTFS-BLACKBOX.exe processes started from OUR
        vendor folder (they lock the exe and block patching). Returns True if
        anything had to be killed."""
        name = VENDOR_EXE.name
        try:
            wanted = os.path.normcase(str(VENDOR_EXE))
        except Exception:                                  # noqa: BLE001
            wanted = None
        killed = False
        deadline = time.time() + wait
        while True:
            try:
                out = subprocess.run(
                    ["tasklist", "/FI", f"IMAGENAME eq {name}", "/FO", "CSV", "/NH"],
                    capture_output=True, text=True, timeout=15,
                    creationflags=0x08000000).stdout
            except Exception:                              # noqa: BLE001
                return killed
            pids = []
            for line in out.splitlines():
                parts = line.split('","')
                if len(parts) >= 2 and parts[0].strip('"').lower() == name.lower():
                    try:
                        pids.append(int(parts[1].strip('"')))
                    except ValueError:
                        pass
            if not pids:
                return killed
            for pid in pids:
                img = _pid_image_path(pid)
                # only touch instances running OUR vendored copy (or unknown)
                if img is not None and wanted is not None                         and os.path.normcase(img) != wanted:
                    continue
                try:
                    subprocess.run(["taskkill", "/F", "/PID", str(pid)],
                                   creationflags=0x08000000,
                                   stdout=subprocess.DEVNULL,
                                   stderr=subprocess.DEVNULL, timeout=15)
                    killed = True
                except Exception:                          # noqa: BLE001
                    pass
            if time.time() >= deadline:
                return killed
            time.sleep(0.5)

    def close_window(hwnd):
        try:
            _user32.PostMessageW(hwnd, WM_CLOSE, 0, 0)
        except Exception:
            pass

else:  # non-Windows stubs (selftest still works; flashing needs Windows)
    def enum_windows():
        return []

    def find_vendor_window(pid=None):
        return None

    def auto_start_upgrade(hwnd):
        raise RuntimeError("Windows only")

    def kill_vendor_processes(wait=6.0):
        return False

    def close_window(hwnd):
        pass


# ===========================================================================
#  Vendor log watcher
# ===========================================================================
class VendorLogs:
    """Incremental reader for the vendor's LOG/ folder."""

    def __init__(self, logdir: Path):
        self.logdir = logdir
        self.offsets = {}
        self.snapshot()

    def snapshot(self):
        self.offsets = {}
        if self.logdir.is_dir():
            for f in self.logdir.glob("*"):
                try:
                    self.offsets[f.name] = f.stat().st_size
                except OSError:
                    pass

    def read_new(self):
        """Return list of new text lines appended since the snapshot."""
        lines = []
        if not self.logdir.is_dir():
            return lines
        for f in self.logdir.glob("*"):
            try:
                size = f.stat().st_size
            except OSError:
                continue
            off = self.offsets.get(f.name)
            if off is None:
                off = 0
            if size < off:          # file was truncated/rotated
                off = 0
            if size == off:
                continue
            try:
                with open(f, "r", encoding="utf-8", errors="replace") as fh:
                    fh.seek(off)
                    data = fh.read()
                self.offsets[f.name] = size
            except OSError:
                continue
            for ln in data.splitlines():
                ln = ln.strip()
                if ln:
                    lines.append(ln)
        return lines


# ===========================================================================
#  Flasher (worker thread logic)
# ===========================================================================
class FlashAborted(RuntimeError):
    pass


class Flasher:
    """Full pipeline: patch -> launch vendor -> auto-start -> follow logs."""

    def __init__(self, fw_path: Path, ui_cb, done_cb):
        self.fw_path = fw_path
        self.ui = ui_cb          # ui("message", kind)
        self.done = done_cb      # done(ok: bool, message: str)
        self.stop_flag = threading.Event()
        self.proc = None
        self.hwnd = None

    # -- helpers ----------------------------------------------------------
    def _ui(self, msg, kind="info"):
        """UI message + persistent run log."""
        flog(msg)
        self.ui(msg, kind)

    def _check_stop(self):
        if self.stop_flag.is_set():
            raise FlashAborted("cancelled by user")

    def _sleep(self, seconds):
        end = time.time() + seconds
        while time.time() < end:
            self._check_stop()
            time.sleep(0.2)

    # -- stages -----------------------------------------------------------
    def run(self):
        try:
            ok, msg = self._flow()
            self.done(ok, msg)
        except FlashAborted as exc:
            self.done(False, str(exc))
        except PatchError as exc:
            self.done(False, f"preflight/patch error: {exc}")
        except Exception as exc:                      # noqa: BLE001
            self.done(False, f"unexpected error: {exc}")

    def _flow(self):
        # 0. clear any leftover vendor instance (a stuck window must never
        #    block the next attempt)
        self._close_stale_vendor()

        ok, msg, stalled = self._attempt(self.fw_path, connect_timeout=150)
        if ok or not stalled:
            return ok, msg

        # ---- the known stall: "Verification timeout!" ---------------------
        # A write interrupted mid-transfer (e.g. the updater was closed while
        # flashing) leaves a PENDING update cycle in the pedal, pinned to the
        # file that was being staged. While pinned, flashing ANY other file
        # stalls (the pedal asks the 0xA47FF marker and goes silent) and the
        # vendor gives up. Device-proven recovery: complete the pending
        # cycle first — flash THE PINNED FILE (it skips the marker and flies)
        # — then re-run the requested flash, which then also flies clean.
        # The pinned file is unknown, so try every candidate we have.
        ensure_firmware_files()
        candidates, seen = [], set()
        for cand in (CUSTOM_FW, FACTORY_FW, load_last_file()):
            if not cand or not cand.is_file():
                continue
            if cand.name == self.fw_path.name or cand.name in seen:
                continue
            seen.add(cand.name)
            candidates.append(cand)
        if not candidates:
            return False, (
                f"{msg} — and the automatic recovery could not run: no other "
                "firmware file is available (put the .fwsc that was being "
                "flashed when the pedal's cycle was interrupted back in the "
                "firmware/ folder and run again)")
        self._ui("The updater hit the known stall (pending firmware cycle in "
                 "the pedal) — recovery: completing the pending cycle by "
                 "flashing its pinned firmware…", "err")
        recovered = False
        for cand in candidates:
            self._close_stale_vendor()
            self._ui(f"recovery attempt: {cand.name}", "dim")
            ok2, _msg2, _ = self._attempt(cand, connect_timeout=300)
            if ok2:
                recovered = True
                break
        if not recovered:
            return False, ("the stall could not be cleared automatically: no "
                           "candidate firmware completed the pedal's pending "
                           "cycle. Put the .fwsc you were flashing when it was "
                           "interrupted in the firmware/ folder and run again, "
                           "or power-cycle the pedal (hold the power button "
                           "2-3 minutes)")
        self._ui("Pending cycle completed — re-running the requested flash…", "info")
        self._close_stale_vendor()
        ok3, msg3, _ = self._attempt(self.fw_path, connect_timeout=300)
        if ok3:
            return True, ("flashed successfully after auto-recovery of a "
                          "pending firmware cycle — " + msg3)
        return False, msg3

    def _attempt(self, fw_path, connect_timeout=150):
        """One complete flash attempt. Returns (ok, message, stalled)."""
        # 1. patch a fresh working copy of the vendor exe
        self._ui("Preparing vendor updater (restore pristine + patch)…", "info")
        info = build_patched_exe(fw_path)
        self._ui(f"Patched OK — firmware: {info['firmware']} "
                f"({info['firmware_sha256'][:12]}…)", "info")
        self._check_stop()

        # 2. launch
        logs = VendorLogs(LOG_DIR)
        self._ota_marker = False
        self._writing = False
        self._ui("Launching vendor updater…", "info")
        try:
            self.proc = subprocess.Popen(
                [str(VENDOR_EXE)], cwd=str(VENDOR_DIR),
                stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL)
        except OSError as exc:
            raise PatchError(f"could not launch vendor exe: {exc}") from exc

        # 3. find its main window
        self._ui("Waiting for the updater window…", "info")
        self.hwnd = None
        deadline = time.time() + 90
        while time.time() < deadline:
            self._check_stop()
            time.sleep(0.5)
            found = find_vendor_window(self.proc.pid)
            if found:
                self.hwnd, _, title = found
                self._ui(f"Updater window found: “{title}”", "info")
                break
            if self.proc.poll() is not None:
                raise PatchError("the vendor updater closed immediately "
                                 "(is the pedal plugged in?)")
        if not self.hwnd:
            raise PatchError("updater window did not appear within 90 s")

        # 4. wait until the pedal is connected (vendor log says so)
        self._ui("Waiting for the pedal to be detected (USB)…", "info")
        connected = False
        deadline = time.time() + connect_timeout
        while time.time() < deadline:
            self._check_stop()
            for ln in logs.read_new():
                self._log_line(ln)
                if any(m in ln for m in MSG_CONNECTED):
                    connected = True
            if connected:
                break
            if self.proc.poll() is not None:
                raise PatchError("the vendor updater exited while connecting")
            time.sleep(0.7)
        if not connected:
            raise PatchError("pedal not detected — check the USB cable and "
                             "power, then retry")

        # 5. auto-start the upgrade (posted click — the cursor never moves)
        self._ui("Starting the upgrade (auto — background click, cursor stays still)…", "info")
        started = False
        for attempt in range(1, 9):
            self._check_stop()
            auto_start_upgrade(self.hwnd)
            t_end = time.time() + 15
            while time.time() < t_end:
                self._check_stop()
                for ln in logs.read_new():
                    self._log_line(ln)
                    if any(m in ln for m in MSG_OTA_START) or self._ota_marker:
                        started = True
                if started:
                    break
                time.sleep(0.6)
            if started:
                break
            self._ui(f"no reaction yet — retry {attempt}/8", "dim")
        if not started:
            raise PatchError("the vendor updater did not start the OTA process "
                             "(its window is still open — you can start it "
                             "manually and watch it)")

        # 6. follow until success / failure
        self._ui("OTA in progress — do NOT unplug the pedal…", "info")
        self._writing = True
        deadline = time.time() + 600
        while time.time() < deadline:
            self._check_stop()
            for ln in logs.read_new():
                self._log_line(ln)
                if any(m in ln for m in MSG_OTA_FAIL):
                    stalled = ("Verification timeout" in ln
                               or "Upgrade timeout" in ln)
                    short = ("verification timeout" if "Verification" in ln
                             else "upgrade timeout" if "Upgrade timeout" in ln
                             else "upgrade failure")
                    return False, f"the updater reported a {short}", stalled
                if any(m in ln for m in MSG_OTA_SUCCESS):
                    self._writing = False
                    self._close_vendor()
                    return True, ("firmware flashed successfully — the pedal "
                                  "reboots itself; USB may drop for 1-3 "
                                  "minutes and then come back"), False
            if self.proc.poll() is not None and self.hwnd:
                if not find_vendor_window(self.proc.pid):
                    time.sleep(2)
                    for ln in logs.read_new():
                        self._log_line(ln)
                        if any(m in ln for m in MSG_OTA_SUCCESS):
                            self._writing = False
                            return True, "firmware flashed successfully", False
            time.sleep(0.7)
        return False, ("timed out waiting for the updater result — check its "
                       "window and retry"), False

    def _close_stale_vendor(self):
        """Close (or kill) any vendor updater left over from a previous run.
        A second instance can never talk to the pedal, and a process that is
        still alive keeps the exe locked so the next patch would fail."""
        found = [(h, p) for (h, p, t) in enum_windows()
                 if WINDOW_TITLE_HINT.lower() in t.lower()]
        if found:
            self._ui("Closing a leftover updater window before starting…", "dim")
            for hwnd, _pid in found:
                close_window(hwnd)
            end = time.time() + 3
            while time.time() < end and find_vendor_window():
                time.sleep(0.4)
        # the window can close while the process lingers (it still holds the
        # exe file lock) — make sure no updater process is left at all
        if kill_vendor_processes(wait=6.0):
            self._ui("Stopped a leftover updater process.", "dim")

    # -- internal ---------------------------------------------------------
    _ota_marker = False
    _writing = False

    def _log_line(self, ln):
        flog("vendor: " + ln)                    # raw line -> run log
        # strip "[date] [LEVEL] " / [ "DEBUG" ] prefixes, keep the message
        text = ln
        i = ln.rfind('"] ')
        if i != -1:
            text = ln[i + 3:].strip('"')
        else:
            j = ln.find("] ")
            if j != -1 and ln.startswith("["):
                text = ln[j + 2:]
        text = text.strip('"').strip()
        if not text or not any(m in text for m in MSG_DISPLAY):
            return                                    # skip debug noise
        kind = "dim"
        if any(m in text for m in MSG_OTA_START):
            kind = "accent"
            self._ota_marker = True
        elif any(m in text for m in MSG_OTA_FAIL):
            kind = "err"
        if any(m in text for m in ("Parsed OTA file", "Device connected",
                                   "Selected device", "USB open result")):
            kind = "accent"
        self._ui(text, kind)

    def _close_vendor(self):
        if self.hwnd:
            time.sleep(3)
            close_window(self.hwnd)
            self.hwnd = None

    def cancel(self):
        self.stop_flag.set()


# ===========================================================================
#  GUI
# ===========================================================================
def run_gui():
    import tkinter as tk
    from tkinter import messagebox, ttk, filedialog

    root = tk.Tk()
    root.title("ANNBLACKBOX — Custom Firmware Installer")
    root.configure(bg=BG)
    root.geometry("700x560")
    root.minsize(640, 500)

    ui_q = queue.Queue()
    worker = {"obj": None}

    # ---------------- layout ----------------
    tk.Label(root, text="ANNBLACKBOX", bg=BG, fg=FG,
             font=("Arial", 22, "bold")).pack(pady=(18, 0))
    tk.Label(root, text="CUSTOM FIRMWARE INSTALLER", bg=BG, fg=FG_DIM,
             font=("Arial", 10, "bold")).pack()

    btn_row = tk.Frame(root, bg=BG)
    btn_row.pack(pady=18)

    def make_button(parent, text, cmd):
        b = tk.Button(parent, text=text, command=cmd, bg=BUTTON, fg=FG,
                      activebackground=BUTTON_HOVER, activeforeground=FG,
                      relief="flat", bd=0, font=("Arial", 10, "bold"),
                      padx=16, pady=9, cursor="hand2", disabledforeground="#7a7a7a")
        b.bind("<Enter>", lambda e: b.config(bg=BUTTON_HOVER) if b["state"] != "disabled" else None)
        b.bind("<Leave>", lambda e: b.config(bg=BUTTON) if b["state"] != "disabled" else None)
        return b

    b_custom = make_button(btn_row, "Install custom firmware", lambda: start_flash("custom"))
    b_custom.pack(side="left", padx=6)
    b_factory = make_button(btn_row, "Restore V20 factory", lambda: start_flash("factory"))
    b_factory.pack(side="left", padx=6)
    b_cancel = make_button(btn_row, "Cancel", lambda: on_cancel())
    b_cancel.pack(side="left", padx=6)

    status_var = tk.StringVar(value="»  ready — plug the pedal via USB, then choose an action")
    tk.Label(root, textvariable=status_var, bg=BG, fg=FG_DIM, anchor="w",
             font=("Arial", 10, "bold")).pack(fill="x", padx=24)

    style = ttk.Style(root)
    try:
        style.theme_use("clam")
    except tk.TclError:
        pass
    style.configure("BB.Horizontal.TProgressbar", troughcolor=BUTTON,
                    background=ACCENT, bordercolor=BG, lightcolor=ACCENT,
                    darkcolor=ACCENT, thickness=14)
    style.configure("BB.Vertical.TScrollbar", troughcolor=BG, background=BUTTON,
                    bordercolor=BG, arrowcolor=FG_DIM, lightcolor=BUTTON,
                    darkcolor=BUTTON)
    pb = ttk.Progressbar(root, style="BB.Horizontal.TProgressbar",
                         maximum=100, value=0)
    pb.pack(fill="x", padx=24, pady=(8, 14))

    # ---------------- credits footer (packed before the log area) ----------
    footer = tk.Frame(root, bg=BG)
    footer.pack(side="bottom", fill="x", pady=10)

    def mk_link(parent, text, url):
        lbl = tk.Label(parent, text=text, bg=BG, fg=FG_DIM,
                       font=("Arial", 9, "underline"), cursor="hand2")
        lbl.bind("<Button-1>", lambda e: webbrowser.open(url))
        lbl.bind("<Enter>", lambda e: lbl.config(fg=ACCENT))
        lbl.bind("<Leave>", lambda e: lbl.config(fg=FG_DIM))
        return lbl

    mk_link(footer, CREDITS_AUTHOR_TEXT, CREDITS_AUTHOR_URL).pack(side="left", padx=(24, 6))
    tk.Label(footer, text="·", bg=BG, fg=FG_DIM, font=("Arial", 9)).pack(side="left")
    mk_link(footer, CREDITS_REPO_TEXT, CREDITS_REPO_URL).pack(side="left", padx=6)

    def open_logs_folder(_event=None):
        try:
            LOGS_DIR.mkdir(exist_ok=True)
            os.startfile(str(LOGS_DIR))              # noqa: S606 (Windows)
        except Exception:                            # noqa: BLE001
            pass

    tk.Label(footer, text="·", bg=BG, fg=FG_DIM, font=("Arial", 9)).pack(side="left")
    logs_lbl = tk.Label(footer, text="logs", bg=BG, fg=FG_DIM,
                        font=("Arial", 9, "underline"), cursor="hand2")
    logs_lbl.bind("<Button-1>", open_logs_folder)
    logs_lbl.bind("<Enter>", lambda e: logs_lbl.config(fg=ACCENT))
    logs_lbl.bind("<Leave>", lambda e: logs_lbl.config(fg=FG_DIM))
    logs_lbl.pack(side="left", padx=6)

    log_frame = tk.Frame(root, bg=BG)
    log_frame.pack(fill="both", expand=True, padx=24, pady=(0, 4))
    log_box = tk.Text(log_frame, height=13, bg="#101010", fg=FG_DIM,
                      insertbackground=FG, relief="flat", bd=0,
                      font=("Consolas", 9), wrap="word", state="disabled")
    sb = ttk.Scrollbar(log_frame, style="BB.Vertical.TScrollbar",
                       orient="vertical", command=log_box.yview)
    log_box.configure(yscrollcommand=sb.set)
    sb.pack(side="right", fill="y")
    log_box.pack(side="left", fill="both", expand=True)

    _last_line = {"text": None, "t": 0.0}

    def log_add(text, kind="dim"):
        # the vendor writes each message to two log files -> drop the echoes
        now = time.time()
        if text == _last_line["text"] and now - _last_line["t"] < 3.0:
            return
        _last_line["text"], _last_line["t"] = text, now
        flog(text)                                   # persistent run log
        colors = {"dim": FG_DIM, "info": FG, "accent": ACCENT, "err": "#ff5555"}
        log_box.configure(state="normal")
        log_box.insert("end", f"{time.strftime('%H:%M:%S')}  {text}\n")
        log_box.tag_add(kind, f"end-2l linestart", "end-1c")
        log_box.tag_configure(kind, foreground=colors.get(kind, FG_DIM))
        log_box.see("end")
        log_box.configure(state="disabled")

    # ---------------- actions ----------------
    def set_busy(busy):
        st = "disabled" if busy else "normal"
        b_custom.config(state=st, bg=BUTTON if not busy else PANEL)
        b_factory.config(state=st, bg=BUTTON if not busy else PANEL)
        if busy:
            pb.configure(mode="indeterminate")
            pb.start(12)
        else:
            pb.stop()
            pb.configure(mode="determinate")
            pb["value"] = 0

    def start_flash(kind):
        if not IS_WINDOWS:
            messagebox.showerror("ANNBLACKBOX", "This tool is Windows-only.")
            return

        ensure_firmware_files()          # self-heal missing bundled firmwares

        if kind == "custom":
            # let the user pick any ANNBLACKBOX .fwsc (default: the bundled one)
            last = load_last_dir()
            if last and Path(last).is_dir():
                init_dir, init_file = last, ""
            else:
                init_dir = str(CUSTOM_FW.parent if CUSTOM_FW.parent.is_dir() else HERE)
                init_file = CUSTOM_FW.name
            chosen = filedialog.askopenfilename(
                parent=root,
                title="Select the firmware to flash (.fwsc)",
                initialdir=init_dir,
                initialfile=init_file,
                filetypes=[("ANNBLACKBOX firmware", "*.fwsc"),
                           ("All files", "*.*")])
            if not chosen:
                return                                    # cancelled
            fw_path = Path(chosen)
            save_last_dir(str(fw_path.parent))
            save_last_file(fw_path)
            if not fw_path.is_file():
                messagebox.showerror("ANNBLACKBOX", f"file not found:\n{fw_path}")
                return
            size = fw_path.stat().st_size
            if size != FW_SIZE:
                messagebox.showerror(
                    "ANNBLACKBOX",
                    "This is not a valid BlackBox firmware file.\n\n"
                    f"{fw_path.name}\n"
                    f"size: {size:,} bytes — expected exactly {FW_SIZE:,} bytes\n\n"
                    "Pick a .fwsc built for the BlackBox (e.g. the bundled "
                    "ANNBLACKBOX_custom.fwsc).")
                return
            what = f"CUSTOM firmware\n{fw_path.name}"
        else:
            fw_path = FACTORY_FW
            if not fw_path.is_file():
                messagebox.showerror("ANNBLACKBOX", f"missing firmware file:\n{fw_path}")
                return
            what = f"the FACTORY V20 firmware\n{fw_path.name}"

        if not messagebox.askyesno(
                "ANNBLACKBOX",
                f"Flash {what} onto the pedal?\n\n"
                "• keep the USB cable connected until it finishes\n"
                "• the updater window will open and start by itself\n"
                "• presets are not touched"):
            return

        log_path = open_run_log(("custom" if kind == "custom" else "factory"))
        log_add(f"--- {what.splitlines()[0]}: {fw_path.name} ---", "info")
        if log_path:
            log_add(f"(full log of this run: logs/{log_path.name})", "dim")
        set_busy(True)
        status_var.set("»  preparing…")

        def ui_cb(msg, kind):
            ui_q.put(("log", msg, kind))

        def done_cb(ok, msg):
            ui_q.put(("done", ok, msg))

        fl = Flasher(fw_path, ui_cb, done_cb)
        worker["obj"] = fl
        threading.Thread(target=fl.run, daemon=True).start()

    def on_cancel():
        fl = worker["obj"]
        if fl is not None and not fl.stop_flag.is_set():
            if fl._writing:
                warn = ("The firmware WRITE is in progress right now.\n\n"
                        "Closing the updater mid-write leaves a pending update "
                        "cycle in the pedal — the next flash may stall until "
                        "the tool recovers it (it can, automatically, but it "
                        "takes longer).\n\n"
                        "Close anyway?")
            else:
                warn = ("A flash is in progress.\n\n"
                        "Closing now may leave the pedal needing a power-cycle.\n"
                        "Close anyway?")
            if messagebox.askyesno("ANNBLACKBOX", warn):
                fl.cancel()
                fl._close_vendor()
                root.destroy()
        else:
            root.destroy()

    def poll_queue():
        try:
            while True:
                item = ui_q.get_nowait()
                if item[0] == "log":
                    _, msg, kind = item
                    log_add(msg, kind if kind != "info" else "info")
                    if any(m in msg for m in MSG_OTA_START):
                        status_var.set("»  OTA in progress — do NOT unplug…")
                    elif any(m in msg for m in MSG_CONNECTED):
                        status_var.set("»  pedal connected")
                    elif "Parsed OTA file" in msg:
                        status_var.set("»  " + msg)
                elif item[0] == "done":
                    _, ok, msg = item
                    set_busy(False)
                    log_add(("OK: " if ok else "FAILED: ") + msg,
                            "accent" if ok else "err")
                    status_var.set(("»  done — " if ok else "»  failed — ") + msg)
                    if ok:
                        pb["value"] = 100
                    else:
                        messagebox.showwarning("ANNBLACKBOX", msg)
                    worker["obj"] = None
        except queue.Empty:
            pass
        root.after(150, poll_queue)

    root.after(150, poll_queue)
    root.mainloop()


# ===========================================================================
#  CLI (testing / headless)
# ===========================================================================
def cli_selftest():
    """Patch mechanics on a temp copy — does not touch the real vendor exe."""
    print("== SELFTEST: patch engine on a temporary copy ==")
    tmp = Path(tempfile.gettempdir()) / "annblackbox_selftest.exe"
    shutil.copyfile(PRISTINE_EXE, tmp)
    results = []
    for fw in (CUSTOM_FW, FACTORY_FW):
        fw_bytes = fw.read_bytes()
        with open(tmp, "r+b") as fh:
            fh.seek(FW_OFFSET)
            fh.write(fw_bytes)
            fh.seek(SITE_VERSION_OFFSET)
            fh.write(SITE_VERSION_PATCH)
            fh.seek(SITE_UIGATE_OFFSET)
            fh.write(SITE_UIGATE_PATCH)
        with open(tmp, "rb") as fh:
            fh.seek(FW_OFFSET)
            ok_fw = fh.read(FW_SIZE) == fw_bytes
            fh.seek(SITE_VERSION_OFFSET)
            ok_v = fh.read(6) == SITE_VERSION_PATCH
            fh.seek(SITE_UIGATE_OFFSET)
            ok_u = fh.read(2) == SITE_UIGATE_PATCH
        ok = ok_fw and ok_v and ok_u
        results.append(ok)
        print(f"  {fw.name}: firmware={'OK' if ok_fw else 'BAD'} "
              f"version-guard={'OK' if ok_v else 'BAD'} "
              f"ui-gate={'OK' if ok_u else 'BAD'}")
    tmp.unlink(missing_ok=True)
    print("SELFTEST:", "PASS" if all(results) else "FAIL")
    return 0 if all(results) else 1


def cli_probe(kind="factory"):
    """Launch the patched exe, confirm it parses the firmware, then close it."""
    fw = CUSTOM_FW if kind == "custom" else FACTORY_FW
    print(f"== PROBE: launch patched vendor exe with {fw.name} (no flashing) ==")
    if find_vendor_window():
        print("ERROR: an M-UPGRADE window is already open — close it first")
        return 1
    info = build_patched_exe(fw)
    print("patched:", info["firmware"], info["firmware_sha256"][:16])
    logs = VendorLogs(LOG_DIR)
    proc = subprocess.Popen([str(VENDOR_EXE)], cwd=str(VENDOR_DIR))
    hwnd = None
    deadline = time.time() + 90
    while time.time() < deadline:
        time.sleep(0.5)
        found = find_vendor_window(proc.pid)
        if found:
            hwnd, _, title = found
            print("window found:", repr(title), "hwnd", hwnd)
            break
    if not hwnd:
        print("PROBE: FAIL (no window)")
        proc.kill()
        return 1
    time.sleep(6)
    parsed = False
    for ln in logs.read_new():
        print("  log:", ln)
        if "Parsed OTA file" in ln:
            parsed = True
    close_window(hwnd)
    time.sleep(2)
    if proc.poll() is None:
        proc.kill()
        time.sleep(1)
    restore_pristine()          # leave the shipped folder clean
    print("PROBE:", "PASS" if parsed else "FAIL (no 'Parsed OTA file' in log)")
    return 0 if parsed else 1


def cli_flash(kind_or_path):
    """Headless flash (console output instead of GUI).
    kind_or_path: 'custom', 'factory' or a path to a .fwsc file."""
    ensure_firmware_files()
    open_run_log("cli")
    if kind_or_path == "custom":
        fw = CUSTOM_FW
    elif kind_or_path == "factory":
        fw = FACTORY_FW
    else:
        fw = Path(kind_or_path)
    save_last_file(fw)                       # recovery candidate for next time
    print(f"== FLASH: {fw} ==")
    done = {}
    fl = Flasher(fw,
                 lambda m, k: print("  |", m),
                 lambda ok, m: done.update(ok=ok, msg=m))
    fl.run()
    print("RESULT:", "OK" if done.get("ok") else "FAILED", "-", done.get("msg"))
    return 0 if done.get("ok") else 1


