def _out(msg):
    if sys.stdout:
        print(msg)


def ensure_dependencies():
    """Check everything needed to RUN this tool and try to install what is
    missing (this tool only needs the Python standard library; the one real
    dependency is tkinter for the GUI). Returns (problems, gui_ok)."""
    problems = []
    if sys.version_info < (3, 8):
        problems.append(f"Python {sys.version.split()[0]} is too old — "
                        "Python 3.8 or newer is required")
    try:
        import tkinter  # noqa: F401
        return problems, True
    except Exception:                                     # noqa: BLE001
        pass

    # tkinter missing: try pip (works on some Python builds), then explain
    _out("tkinter is missing — trying to install it with pip …")
    try:
        subprocess.run([sys.executable, "-m", "pip", "install", "--user", "tk"],
                       capture_output=True, text=True, timeout=300,
                       creationflags=(0x08000000 if IS_WINDOWS else 0))
    except Exception:                                     # noqa: BLE001
        pass
    try:
        import importlib
        importlib.invalidate_caches()
        import tkinter  # noqa: F401
        return problems, True
    except Exception:                                     # noqa: BLE001
        pass
    problems.append(
        "tkinter (Tcl/Tk) is missing and could not be installed "
        "automatically. Fix: reinstall Python from python.org and make sure "
        "the option 'tcl/tk and IDLE' is checked (it is by default).")
    return problems, False


def _native_message(title, text, error=True):
    try:
        if IS_WINDOWS:
            ctypes.windll.user32.MessageBoxW(0, text, title,
                                             0x10 if error else 0x40)
            return
    except Exception:                                     # noqa: BLE001
        pass
    _out(text)


def main():
    args = sys.argv[1:]
    problems, gui_ok = ensure_dependencies()
    for pr in problems:
        _out("dependency problem: " + pr)
    if not gui_ok:
        _native_message("ANNBLACKBOX — missing dependency",
                        chr(10).join(problems))
        return 3
    if IS_WINDOWS:
        ensure_firmware_files()          # self-heal missing bundled firmwares
    if args and args[0] == "--selftest":
        return cli_selftest()
    if args and args[0] == "--probe":
        kind = args[1] if len(args) > 1 else "factory"
        return cli_probe(kind if kind in ("custom", "factory") else "factory")
    if args and args[0] == "--flash":
        kind = args[1] if len(args) > 1 else "custom"
        return cli_flash(kind)
    run_gui()
    return 0


if __name__ == "__main__":
    if not IS_WINDOWS and not sys.argv[1:]:
        print("ANNBLACKBOX installer is Windows-only (the vendor OTA engine is "
              "a Windows application).")
        sys.exit(2)
    sys.exit(main())
